reference_solution.python:
class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        import math
        l, r = 1, max(piles)
        res = r
        while l <= r:
            k = (l + r) // 2
            total_time = sum(math.ceil(p / k) for p in piles)
            if total_time <= h:
                res = k
                r = k - 1
            else:
                l = k + 1
        return res

reference_solution.javascript:
function minEatingSpeed(piles, h) {
    let l = 1, r = Math.max(...piles);
    let res = r;
    while (l <= r) {
        const k = Math.floor((l + r) / 2);
        let totalTime = 0;
        for (const p of piles) {
            totalTime += Math.ceil(p / k);
        }
        if (totalTime <= h) {
            res = k;
            r = k - 1;
        } else {
            l = k + 1;
        }
    }
    return res;
}
